<script lang="ts">
    import { onMount } from 'svelte';
    import MinecraftAvatar from '$lib/components/ui/MinecraftAvatar.svelte';
    import { translateUi as t } from '$lib/i18n/useTranslation.svelte';
    import { button } from './serverButton';
    import { moderateServer, serverManage, type ServerPlayer, type LocalServerState } from '$lib/api/localServers';
    let { id, serverState, pro }: { id: string; serverState: LocalServerState | null; pro: boolean } = $props();
    let history = $state<ServerPlayer[]>([]); let banned = $state<{ name: string; uuid: string }[]>([]); let name = $state(''); let action = $state('whitelist add'); let busy = $state(false); let error = $state(''); let sent = $state(false); let confirm = $state(''); let disposed = false;
    const players = $derived(serverState?.players ?? history);
    let allowed = $state<{ name: string; uuid: string }[]>([]); let operators = $state<{ name: string; uuid: string }[]>([]);
    async function load() { const next = await serverManage<{ players: ServerPlayer[]; banned: { name: string; uuid: string }[]; whitelist: { name: string; uuid: string }[]; operators: { name: string; uuid: string }[] }>({ action: 'players', id }); if (!disposed) { history = next.players; banned = next.banned; allowed = next.whitelist || []; operators = next.operators || []; } }
    onMount(() => { let timer: ReturnType<typeof setTimeout>; async function poll() { if (!busy) { try { await load(); } catch (cause) { if (!disposed) error = String(cause); } } if (!disposed) timer = setTimeout(poll, document.hidden ? 6000 : 2500); } void poll(); return () => { disposed = true; clearTimeout(timer); }; });
    async function moderate(command: string, player: string) { if (busy) return; busy = true; error = ''; sent = false; try { await moderateServer(id, command, player, '', [...players, ...banned, ...allowed, ...operators].find(entry => entry.name.toLowerCase() === player.toLowerCase())?.uuid); if (!disposed) { sent = true; confirm = ''; await load(); } } catch (cause) { if (!disposed) error = String(cause); } finally { if (!disposed) busy = false; } }
</script>

<section class="space-y-5 p-5 sm:p-6">
    <div><h3 class="font-semibold">{t('serverPanel.players')}</h3><p class="mt-2 text-sm leading-6 text-fg-muted">{t('serverPanel.playersHelp')}</p></div>
    {#if error}<p role="alert" class="break-words text-sm text-danger">{error}</p>{/if}{#if sent}<p role="status" class="text-sm text-success">{t('serverPanel.commandSent')}</p>{/if}
    <div class="grid grid-cols-3 gap-3">{#each [{ name: 'online', count: serverState?.playersOnline ?? 0 }, { name: 'knownOffline', count: players.filter(player => !player.online).length }, { name: 'unique', count: players.length }] as metric}<div class="rounded-2xl border border-border p-4"><p class="text-2xl font-semibold tabular-nums">{metric.count}</p><p class="mt-2 text-xs text-fg-muted">{t(`serverPanel.${metric.name}`)}</p></div>{/each}</div>
    {#if serverState && !serverState.historyComplete}<p class="text-xs leading-5 text-warning">{t('serverPanel.partialHistory')}</p>{/if}
    <form class="flex flex-wrap gap-3" onsubmit={event => { event.preventDefault(); confirm = `${action}:${name}`; }}><label class="min-w-36 flex-1"><span class="sr-only">{t('serverPanel.playerName')}</span><input class="w-full rounded-xl border border-border bg-bg-subtle px-3 py-3 text-sm" placeholder={t('serverPanel.playerName')} maxlength="16" pattern={'[A-Za-z0-9_]{1,16}'} required bind:value={name} /></label><label><span class="sr-only">{t('serverPanel.action')}</span><select class="rounded-xl border border-border bg-bg-subtle px-3 py-3 text-sm" bind:value={action}>{#each ['whitelist add', 'whitelist remove', 'ban', 'pardon', 'op', 'deop', 'kick'] as command}<option value={command}>{t(`serverPanel.action_${command.replaceAll(' ', '_')}`)}</option>{/each}</select></label><button type="submit" class={button({ variant: 'secondary' })} disabled={busy || serverState?.phase !== 'running' || !pro}>{t('serverPanel.apply')}</button></form>
    {#if confirm}<div class="space-y-3 rounded-xl border border-warning/30 p-4"><p class="text-sm">{t('serverPanel.moderateConfirm')} <strong>{confirm.split(':')[1]}</strong> · {t(`serverPanel.action_${confirm.split(':')[0].replaceAll(' ', '_')}`)}</p><div class="flex gap-2"><button type="button" class={button({ variant: 'primary', size: 'sm' })} disabled={busy} onclick={() => moderate(confirm.split(':')[0], confirm.split(':')[1])}>{t('serverPanel.confirm')}</button><button type="button" class={button({ variant: 'ghost', size: 'sm' })} onclick={() => confirm = ''}>{t('localServer.cancel')}</button></div></div>{/if}
    {#each players as player (player.uuid)}<article class="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border p-4"><div class="flex min-w-0 items-center gap-4"><MinecraftAvatar username={player.name} avatarUrl={`https://mc-heads.net/avatar/${player.uuid}/64`} status={player.online ? 'online' : 'offline'} class="h-12 w-12" /><div class="min-w-0"><p class="flex items-center gap-2 text-sm font-semibold"><span class="h-2 w-2 rounded-full {player.online ? 'bg-success' : 'bg-fg-muted'}"></span>{player.name}</p><p class="mt-2 text-xs text-fg-muted">{t(player.online ? 'serverPanel.online' : 'serverPanel.knownOffline')}</p></div></div><div class="flex gap-2"><button type="button" class={button({ variant: 'secondary', size: 'sm' })} disabled={busy || serverState?.phase !== 'running' || !pro || !player.online} onclick={() => confirm = `kick:${player.name}`}>{t('serverPanel.action_kick')}</button><button type="button" class={button({ variant: 'danger', size: 'sm' })} disabled={busy || serverState?.phase !== 'running' || !pro} onclick={() => confirm = `ban:${player.name}`}>{t('serverPanel.action_ban')}</button></div></article>{/each}
    {#if !players.length}<p class="rounded-xl border border-dashed border-border p-6 text-sm text-fg-muted">{t('serverPanel.noPlayers')}</p>{/if}
    {#if allowed.length || operators.length}<div class="space-y-3 rounded-xl border border-border p-4">{#if allowed.length}<p class="text-sm"><strong>Whitelist:</strong> {allowed.map(player => player.name).join(', ')}</p>{/if}{#if operators.length}<p class="text-sm"><strong>{t('serverPanel.operators')}:</strong> {operators.map(player => player.name).join(', ')}</p>{/if}</div>{/if}
    {#if banned.length}<h4 class="font-semibold">{t('serverPanel.banned')}</h4>{#each banned as player}<div class="flex items-center justify-between gap-3 rounded-xl border border-border p-3"><span class="text-sm">{player.name}</span><button type="button" class={button({ variant: 'secondary', size: 'sm' })} disabled={busy || serverState?.phase !== 'running' || !pro} onclick={() => confirm = `pardon:${player.name}`}>{t('serverPanel.action_pardon')}</button></div>{/each}{/if}
</section>
